import { ok, fail } from './result.js';
import { balanceDue } from './payments.js';
import { isValidDate, daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Get invoices that are overdue.
 * @param {Array} invoices
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {{ ok: boolean, value?: Array, error?: string }}
 */
export function overdueInvoices(invoices, asOf) {
  if (!isValidDate(asOf)) return fail('DATE_INVALID');

  const overdue = invoices
    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

/**
 * Get VAT summary across invoices.
 * @param {Array} invoices
 * @returns {{ ok: boolean, value?: Array }}
 */
export function vatSummary(invoices) {
  const rates = new Map();

  const eligibleInvoices = invoices.filter(
    (inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid'
  );

  for (const invoice of eligibleInvoices) {
    for (const line of invoice.lines) {
      const lineTotal = line.qty * line.unitPrice;
      const lineDiscount = roundCents(lineTotal * line.discountPercent / 100);
      const lineBase = lineTotal - lineDiscount;
      const lineVat = roundCents(lineBase * line.vatRate / 100);

      const rate = line.vatRate;
      if (!rates.has(rate)) {
        rates.set(rate, { base: 0, vat: 0 });
      }
      const current = rates.get(rate);
      rates.set(rate, { base: current.base + lineBase, vat: current.vat + lineVat });
    }
  }

  const result = Array.from(rates, ([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);

  return ok(result);
}

/**
 * Calculate late fee for an invoice.
 * Late fee is 0.04% of the balance due per day overdue.
 * @param {{ status: string, dueDate: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {{ ok: boolean, value?: number, error?: string }}
 */
export function lateFee(invoice, asOf) {
  if (!isValidDate(asOf)) return fail('DATE_INVALID');

  if (invoice.status === 'draft' || invoice.status === 'paid') {
    return ok(0);
  }

  if (invoice.dueDate >= asOf) {
    return ok(0);
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const feeAmount = roundCents(due * 0.0004 * daysOverdue);

  return ok(feeAmount);
}

