test('dashboard with mixed statuses and overdue', () => {
  const invoices = [
    createInvoice({ status: 'draft', customerId: 'C-001', dueDate: '2026-10-10', lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 5, unitPrice: 10000, vatRate: 0, discountPercent: 0 }] }),
    createInvoice({ status: 'issued', customerId: 'C-002', dueDate: '2026-10-12', lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 3, unitPrice: 10000, vatRate: 0, discountPercent: 0 }] }),
    createInvoice({ status: 'partially_paid', customerId: 'C-003', dueDate: '2026-10-08', payments: [{ amount: 20000, date: '2026-10-12' }], lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 5, unitPrice: 10000, vatRate: 0, discountPercent: 0 }] }),
    createInvoice({ status: 'paid', customerId: 'C-001', dueDate: '2026-10-09', lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 2, unitPrice: 10000, vatRate: 0, discountPercent: 0 }] }),
  ];
  const r = dashboard(invoices, '2026-10-15');

  assert.equal(r.ok, true);
  assert.equal(r.value.counts.draft, 1);
  assert.equal(r.value.counts.issued, 1);
  assert.equal(r.value.counts.partially_paid, 1);
  assert.equal(r.value.counts.paid, 1);
  // Outstanding: issued (30000) + partially_paid (30000) = 60000
  assert.equal(r.value.outstanding, 60000);
  // Overdue: all three have dueDate < 2026-10-15, but only issued and partially_paid count
  assert.equal(r.value.overdue.count, 2);
  assert.equal(r.value.overdue.amount, 60000);
  // Top customers: C-002 (30000), C-003 (30000), C-001 (0)
  assert.equal(r.value.topCustomers.length, 2);
});
